import { btpUnits } from './courseGuides.js'

// Original condensed study notes and practice questions, not SAP quiz answers.
// Source links identify the reviewed lesson supporting each chapter.
const course = (slug) => `https://learning.sap.com/courses/${slug}`
const urls = {
  btp: course('exploring-sap-business-technology-platform'),
  operations: course('operating-sap-business-technology-platform'),
  cloudFoundry: course('developing-applications-for-sap-btp-cloud-foundry-runtime'),
  cap: course('introduction-to-sap-cloud-application-programming-model'),
  extensions: course('develop-extensions-with-cap-following-the-sap-btp-developer-s-guide'),
  fiori: 'https://developers.sap.com/tutorials/add-fiori-elements-uis',
  cleanCore: course('managing-clean-core-for-sap-cloud-erp'),
  integration: course('sap-cloud-platform-integration-service-overview'),
  administration: course('administering-sap-integration-suite'),
}
const section = (title, text, example, remember, question, answer, source) => ({
  title, paragraphs: text.split('\n\n'), example, remember, question, answer, source,
})
const source = (key, slug) => `${urls[key]}/${slug}`

export const summaryForResource = (resource) => {
  if (resource?.includes('/learning-journeys/developing-with-sap-integration-suite')) return 'integration'
  if (resource?.includes('discovery-center.cloud.sap/missiondetail/4327/4608')) return 'extensions'
  return Object.keys(urls).find((key) => resource === urls[key] || resource?.startsWith(`${urls[key]}/`))
}

export const getReadingMinutes = (guide) => {
  const text = JSON.stringify({ intro: guide.intro, terms: guide.terms, sections: guide.sections, lessons: guide.lessons })
  return Math.max(1, Math.ceil(text.split(/\s+/).length / 200))
}

export const courseSummaries = {
  extensions: {
    title: 'Develop Extensions with CAP Following the SAP BTP Developer’s Guide',
    intro: 'Follow the complete extension lifecycle: model a service, provide a UI, add business logic, secure it, consume another system, deploy it, and make it accessible to users.',
    coverage: 'All eight course units. Weeks 5, 6, and 12 use this same course, so they share this guide.',
    terms: [['Side-by-side extension', 'An application outside the ERP core that integrates through supported interfaces.'], ['OData', 'An HTTP-based protocol with service metadata and standard data operations.'], ['XSUAA', 'Authorization and trust services used in the course’s Cloud Foundry architecture.'], ['MTA', 'A package describing related application modules and resources.'], ['Work Zone', 'A central access point for business applications.']],
    sections: [
      section('Discovering CAP and side-by-side extensibility', 'An extension adds behavior that standard business software does not provide for a specific need. Side-by-side development places that application on BTP and connects it through supported interfaces. The extension has its own lifecycle while the ERP system remains responsible for its core business transactions.\n\nCAP provides modeling and runtime support for the extension. Choose this approach because the requirement benefits from a separate application, not because every customization must be external. Simple supported in-app changes can also be appropriate.', 'A custom product approval workflow can run separately and submit approved changes through an ERP API.', 'Clean Core is about supported, maintainable extension choices, not a ban on all extensions.', 'Does a BTP extension need to modify ERP database tables directly?', 'No. Use the supported API contract and appropriate authorization.', source('extensions', 'identifying-the-need-for-side-by-side-extensibility_f1e838f0-f02a-43b4-8896-cedc25a7d5d0')),
      section('Setting up the project and understanding OData', 'Model business entities and define which ones your service exposes. OData supplies metadata and standard data access conventions. GET reads, POST creates, PATCH updates selected properties, and DELETE removes a resource. Consumers need both the endpoint and its contract.\n\nJSON commonly carries structured application data. YAML is often used for configuration. A syntactically valid document can still violate the service’s business rules. Separate understanding the payload format from understanding which fields and operations the API permits.', 'A partial price update should send the intended changed properties rather than accidentally replacing unrelated product details.', 'Transport format and business meaning are different layers.', 'Does valid JSON prove that an order is valid?', 'No. Required fields, types, references, permissions, and business constraints can still fail.', source('extensions', 'introducing-the-odata-protocol_fd5e2134-54e9-456f-af87-02b0c228dbd7')),
      section('Serving and generating user interfaces', 'Fiori elements interprets service metadata and annotations to provide common business screens. CAP supports UI-related features such as search, value help, and draft handling. UI modules belong alongside the application but remain consumers of its service contract.\n\nA List Report helps users find records; an Object Page presents an individual object. Annotations guide presentation and interactions. They do not replace backend validation or authorization. A single CAP project can support more than one application interface.', 'A manager searches the Product List, opens an Object Page, and edits a draft before saving the active record.', 'Draft state and saved business state are not the same thing.', 'Does hiding an edit button secure the update API?', 'No. The backend must enforce the required permission independently.', source('extensions', 'serving-user-interfaces-in-cap_e495a107-badf-4767-9d3d-4178d934437e')),
      section('Adding custom business logic and errors', 'CAP processes service requests as events. Register handlers for relevant operations and entities. Before handlers are useful for validation and preparation; on handlers implement or intercept processing; after handlers can adjust results. Preserve generic behavior when it already solves the problem.\n\nThe request object gives access to request context and data and supports reporting errors. Design errors that explain the failure without exposing secrets. Reject invalid work before it is committed, and consider how a partial update differs from a create request.', 'Reject a negative product price before persistence; enrich a read result with a calculated display value afterward.', 'An after handler is not a universal substitute for validating input before a write.', 'Which handler phase suits checking a submitted price before creation?', 'Before. The request can be rejected before generic create processing proceeds.', source('extensions', 'explaining-event-handling-in-cap_c5e6d965-01b0-47b2-a8a3-46a325f1bce8')),
      section('Authorization and trust', 'The course uses XSUAA and a trusted identity provider to support secured application access. Business roles are different from platform administration rights. CDS restrictions express what roles or conditions the application requires; role assignment connects users to the intended access.\n\nThink through the whole request: the caller authenticates, obtains appropriate trusted credentials, reaches the application, and is checked against its access rules. A token must be valid for the intended application and operation. Local mocked users are useful during development but do not establish productive security.', 'Give viewers read access and managers update access, then test both through direct service requests.', 'Role definition, role assignment, and runtime enforcement must agree.', 'Why test a forbidden request as well as an allowed request?', 'Because a service that lets everyone through can appear to work while failing its security requirements.', source('extensions', 'describing-authorization-and-trust-management-xsuaa-_cbf0d0c5-29ec-4685-9cf4-487156b41284')),
      section('External services and testing', 'An external service is a dependency with its own contract, availability, and security. Model or import the interface as appropriate, configure the connection, and call it through the application’s service layer. Keep remote credentials and environment-specific addresses out of business logic.\n\nTest successful responses, rejected requests, and unavailable dependencies. Mocks make tests repeatable but cannot prove real connectivity or production permissions. Separate unit tests for local rules from integration checks that exercise actual connected components.', 'A product app reads supplier details from another service. Decide what the user sees if that service is unavailable instead of returning an unexplained crash.', 'A passing mock test is evidence about your logic, not the real network path.', 'What remains to verify after an external-service mock passes?', 'The real endpoint, credentials, permissions, payload compatibility, and failure behavior.', source('extensions', 'explaining-extensibility-and-connectivity-in-cap_e2211ec4-177c-4e8b-a614-57b9971ec57f')),
      section('Deployment', 'Deployment converts local project artifacts into a configured application in the target environment. CAP can target Cloud Foundry and Kyma. The course’s Cloud Foundry path uses a multi-target application to coordinate related modules and resources.\n\nDistinguish build-time packaging from runtime configuration. Service bindings, productive persistence, security, and routes must fit the target. After deployment, verify a real authenticated business request. A green deployment log alone does not prove that all dependencies are usable.', 'Document the product service, database resource, security service, and UI hosting so the relationships are understandable.', 'An MTA is a coordinated application package, not simply another word for a database.', 'Can local SQLite success prove the deployed app’s database connection works?', 'No. The deployed persistence configuration and binding must be verified separately.', source('extensions', 'identifying-deployment-options-in-cap_f0136428-e90b-4ec4-802f-d370ba49793b')),
      section('Integrating into SAP Build Work Zone', 'Work Zone provides a central, role-oriented way for people to discover and launch business applications. Publishing application content and making it visible to the correct audience is a separate concern from deploying the backend.\n\nA visible tile does not guarantee that the application’s service calls will succeed. Navigation configuration, destination or routing details, sign-in, and backend permissions must still work together. Verify the experience as the intended business user.', 'A product manager opens the app from a business site and can perform the actions allowed by the backend.', 'Launchpad visibility and service authorization are separate checks.', 'If an app tile is visible, can the user necessarily update its records?', 'No. Visibility makes the app discoverable; the service still decides whether updates are allowed.', source('extensions', 'explaining-sap-build-work-zone-standard-edition')),
    ],
  },
  fiori: {
    title: 'Add SAP Fiori Elements UIs',
    intro: 'Understand how a service becomes a usable business interface. This guide explains the tutorial workflow and the CAP concepts behind it, using a Product List and Product Object Page as your example.',
    coverage: 'The tutorial’s generation, preview, list, and object-page workflow, plus supporting CAP UI concepts. This is a tutorial rather than a standalone SAP Learning quiz course.',
    notice: 'SAP marks the linked tutorial as out of maintenance. The concepts remain useful; use the maintained Discovery Center mission for current setup instructions.',
    terms: [['Fiori / SAPUI5 / Fiori elements', 'Design experience / UI framework / metadata-driven application approach.'], ['List Report / Object Page', 'Find multiple records / work with one business object.'], ['Metadata / annotations', 'Describe the service structure / add semantic and presentation information.'], ['Value help', 'Assistance choosing a valid value or referenced record.']],
    sections: [
      section('How the UI is produced', 'Fiori elements uses OData metadata and annotations to build standard business interfaces on SAPUI5. Metadata describes the entities and properties; annotations add information that influences presentation. You configure a known application pattern instead of hand-building every control.\n\nThe service remains the source of business data and rules. The UI displays and edits that data through the API, so an incorrect service contract cannot be fixed merely by changing a table column.', 'A Product entity exposes name and category; presentation annotations determine which fields appear in a business screen.', 'Service structure and screen layout are related but distinct.', 'Does Fiori elements remove the need for a backend service?', 'No. It consumes a service and its metadata.', urls.fiori),
      section('Generate the application', 'Choose the Fiori elements template and connect it to the appropriate CAP service. Select the main entity that the application will display, then generate the UI module. The tutorial uses a List Report pattern.\n\nBe precise about the selected service and entity. A project can expose multiple services for different audiences. The generated application should use the intended public contract rather than an unrelated entity with a similar name.', 'Choose Products from the product-management service, not an administrative service with internal fields.', 'Template, data source, and main entity are separate generator choices.', 'Why can selecting the wrong service produce a valid but unsuitable app?', 'The generated UI may work technically while exposing the wrong contract or business records.', urls.fiori),
      section('Run and inspect the complete request path', 'Preview the generated interface with the CAP backend available. If data is missing, distinguish an empty result from a failed request. Inspect the service response before assuming the table configuration is wrong.\n\nA UI module, its route to the service, and the backend process are distinct pieces. A successful page load proves that the frontend loaded; it does not prove that every subsequent data request succeeded.', 'An empty Product List might mean no sample data, an active filter, or a failed API call. These require different fixes.', 'First identify which layer fails: page loading, service access, or returned data.', 'Does seeing the application title prove the OData service works?', 'No. The page can load while its data requests fail.', 'https://cap.cloud.sap/docs/guides/uis/'),
      section('Configure the List Report', 'A list supports finding and comparing records. Choose columns that help the user identify the right object, and filters that match actual work. Value help makes it easier to select valid values. Keep user-facing labels understandable and localizable.\n\nThe list should not become a dump of every technical field. Use the service and UI configuration together: one controls what is available, while the other controls how the user works with it.', 'Show product name, category, and price. A category filter is more useful to a manager than displaying several internal identifiers.', 'Hiding a column is a presentation decision, not a security boundary.', 'Is removing a sensitive field from the table enough to protect it?', 'No. If the API still exposes it to the caller, it may remain accessible.', 'https://cap.cloud.sap/docs/guides/security/authorization'),
      section('Configure the Object Page and finish the flow', 'The Object Page gives context and detail for a single business object. Organize related properties into meaningful sections and test navigation from the list. CAP supports draft-enabled UIs where an in-progress edit is distinguished from active data.\n\nVerify the full user journey: find a record, open it, edit allowed fields, save, and see the result. Test invalid input and insufficient permissions as well as successful edits. The quality of the flow depends on both UI configuration and service behavior.', 'A manager changes a product price; a viewer can inspect the same object but cannot persist an unauthorized edit.', 'Draft editing, validation, and authorization solve different parts of the editing experience.', 'Why test direct backend access after verifying the screen?', 'Because callers can bypass the screen; business rules and permissions must remain enforced.', source('extensions', 'serving-user-interfaces-in-cap_e495a107-badf-4767-9d3d-4178d934437e')),
    ],
  },
  cleanCore: {
    title: 'Managing Clean Core for SAP Cloud ERP',
    intro: 'Clean Core keeps ERP maintainable while the business continues to change. It covers processes, extensions, data, integrations, and operations—not only custom code.',
    coverage: 'All four course units, with the five Clean Core principles explained individually.',
    terms: [['Fit-to-standard', 'Start with supported standard behavior before justifying a deviation.'], ['Technical debt', 'Future maintenance burden created by design or implementation choices.'], ['Released interface', 'A supported contract intended for consumption or extension.'], ['Side-by-side / in-app', 'Separate extension application / supported changes within the business application.']],
    sections: [
      section('Why Clean Core matters and who benefits', 'Excessive customization can make upgrades and business changes expensive. Clean Core keeps the system close to supported standards while allowing justified differentiation. Its purpose is sustainable change rather than identical systems for every customer.\n\nUsers benefit from consistent processes and trustworthy data. IT benefits from clearer maintenance boundaries. The business benefits when useful innovations can be adopted without repeatedly untangling old dependencies.', 'Before recreating a legacy approval process, check whether standard behavior already meets the need and whether the difference actually creates value.', 'Clean Core permits well-governed extensions.', 'Does Clean Core mean never extending ERP?', 'No. It means choosing supported, maintainable extensions and governing their lifecycle.', source('cleanCore', 'exploring-why-a-clean-core-is-necessary_b0e7532d-7ced-4643-98d8-a3e36961e891')),
      section('Processes', 'Keep processes understandable and align with standard behavior where it meets the business need. A process difference should have a clear reason and measurable value. Carrying every historical exception forward can preserve complexity without preserving an advantage.\n\nReview the whole process rather than optimizing one screen. A faster entry form has limited value if downstream teams must manually repair inconsistent data.', 'For order approval, distinguish a real regulatory or business requirement from a workaround that existed only because an old system lacked a feature.', 'Standardize ordinary work; justify meaningful differentiation.', 'Should a familiar legacy process automatically be rebuilt unchanged?', 'No. Evaluate whether the requirement still exists and whether standard capabilities address it.', source('cleanCore', 'exploring-how-to-make-business-processes-clean-core-compliant_b3b12b25-4a37-42aa-8442-0811764545b9')),
      section('Extensions', 'Select the extension approach that fits the requirement while respecting supported boundaries. Supported in-app extensions and BTP side-by-side applications can both play a role. Using released interfaces reduces dependence on implementation details that can change during upgrades.\n\nMoving code outside ERP does not automatically make it clean. If an external application depends on undocumented internals, its maintenance risk remains. Record why the extension exists, who owns it, and how it will be checked after changes.', 'A separate product app calling a supported API has a clearer boundary than one relying on internal database tables.', 'Deployment location alone does not establish upgrade safety.', 'Can an external application still violate Clean Core principles?', 'Yes. It can depend on unsupported interfaces or create unmanaged complexity.', source('cleanCore', 'exploring-how-to-make-extensions-clean-core-compliant_d285a299-b152-452f-9cb4-ed3f6e382b10')),
      section('Data', 'Clean data is relevant, reliable, and governed. Duplicate or inconsistent business records weaken processes and analytics even when application code is technically sound. Assign responsibility for data quality and lifecycle rather than treating cleanup as a one-time import task.\n\nIntegration increases the importance of shared meaning. Two systems may use different identifiers for the same customer or product. Mapping and ownership rules prevent conflicting versions of business truth.', 'Document how a shop’s product identifier maps to the corresponding SAP product and who maintains that mapping.', 'A clean codebase can still contain poor business data.', 'Why is data ownership part of Clean Core?', 'Someone must maintain quality and resolve conflicting records; technology alone cannot decide the correct business meaning.', source('cleanCore', 'exploring-how-to-make-data-clean-core-compliant_e6ba82e0-d4e7-4233-8634-2b7b6f6c41e6')),
      section('Integrations', 'Prefer supported interfaces and a clear integration architecture. Document the contract, security, transformations, and error handling. Avoid hidden coupling to the internal structure of another system.\n\nAn integration should remain understandable when either system changes. That requires version awareness, ownership, and a way to observe failures. Reusing suitable standard content can reduce implementation effort, but you still need to validate its fit for your process.', 'A Shopify-to-SAP integration should document its field mapping and supported receiving API so a future upgrade can be assessed.', 'A successful request today does not prove a supported contract for tomorrow.', 'Why are undocumented internal interfaces risky?', 'They can change without the compatibility expectations associated with a supported external contract.', source('cleanCore', 'exploring-how-to-make-integrations-clean-core-compliant_a7ffbb03-e797-4131-85a8-e22826084cb8')),
      section('Operations', 'Maintain the system through controlled changes, monitoring, documented responsibilities, and lifecycle reviews. Clean Core can deteriorate if every urgent fix adds an unmanaged exception. Operational discipline keeps the design maintainable after go-live.\n\nReview obsolete extensions and dependencies, and retain the information needed to understand why they exist. An application that nobody owns is difficult to support even if its original implementation was sound.', 'Include the custom product service in release testing and incident ownership instead of treating it as a forgotten side project.', 'Clean Core is maintained continuously.', 'Is a one-time cleanup enough?', 'No. New changes and business requirements need the same governance.', source('cleanCore', 'exploring-how-to-make-operations-clean-core-compliant_bf44ed71-5e83-4423-aead-ddaab85334a9')),
      section('RISE with SAP and measurement', 'The RISE with SAP methodology incorporates Clean Core into a structured transformation approach. Transformation should assess current complexity, plan improvements, and check progress as the landscape evolves.\n\nA measurement framework makes improvement visible. Use evidence across the Clean Core dimensions rather than declaring success because custom code was moved. Measures need to relate to outcomes and responsibilities; a metric without an action plan is only a report.', 'Review whether unsupported dependencies have decreased and whether documented owners and upgrade checks exist for remaining extensions.', 'Migration to cloud and achieving Clean Core are related but not identical outcomes.', 'Does completing a migration automatically prove a clean core?', 'No. Process, extension, data, integration, and operational choices still need assessment.', source('cleanCore', 'describing-the-clean-core-measurement-framework_a77c16d6-aeeb-41df-bbb4-7d2dc1ebed03')),
    ],
  },
  integration: {
    title: 'SAP Integration Suite: Development and Overview',
    intro: 'Learn to connect systems through governed APIs, message-processing flows, and events. This shared guide supports the Integration Suite learning journey and its overview course in your roadmap.',
    coverage: 'The overview course’s five units, with an additional applied troubleshooting chapter for your integration project. It does not claim to replace every course in the wider learning journey.',
    terms: [['API proxy', 'A managed interface in front of a backend API.'], ['Integration flow (iFlow)', 'A modeled sequence of integration processing steps.'], ['Sender / receiver adapter', 'Inbound / outbound connectivity for a flow.'], ['Event / command', 'A fact that happened / a request to do something.'], ['Topic / queue', 'A publication or subscription address / buffered messages awaiting consumption.']],
    sections: [
      section('Integration strategy and distributed systems', 'Business processes span systems with different data models, protocols, security, and release schedules. Integration must deal with these differences rather than assuming every network request succeeds instantly. SAP’s strategy places Integration Suite within BTP as a shared platform for connected processes.\n\nStart with the business interaction: who initiates it, what information is needed, whether a response is immediate, and what happens when a dependency fails. Choose the integration pattern after answering these questions.', 'A shop can acknowledge an accepted order while its ERP processing happens later, but the customer still needs a clear business status.', 'Technical delivery and business completion are separate milestones.', 'Does a successful network response always prove that the final business process is complete?', 'No. It may acknowledge receipt while later processing is still pending.', source('integration', 'describing-the-integration-strategy-of-sap_b4888fe7-2084-40f1-a89b-ca0f93933c78')),
      section('Choosing Integration Suite capabilities', 'Cloud Integration transforms and coordinates messages between endpoints. API Management governs how APIs are exposed and consumed. Event Mesh supports decoupled event communication. These capabilities can work together, but one does not automatically replace the others.\n\nPrebuilt integration content can accelerate implementation. Inspect its assumptions about endpoints, payloads, authentication, and required configuration. A reusable template still needs to fit the actual systems and business process.', 'Place an API proxy at a controlled entry point, an iFlow where transformation is needed, and event delivery where consumers should process independently.', 'Match a capability to a responsibility instead of adding every capability to every design.', 'Which capability primarily addresses reusable API access policies?', 'API Management. Message transformation and orchestration are primarily Cloud Integration concerns.', source('integration', 'explaining-distributed-architecture-and-their-challenges_ebcaa544-f5ca-4351-b6b6-5eb471ec1464')),
      section('API Management', 'An API proxy provides a managed layer between consumers and a backend. Policies can enforce access and traffic behavior, while analytics helps understand consumption. API lifecycle management includes documentation, version awareness, and a clear contract for consumers.\n\nProtecting the interface does not eliminate the backend’s responsibility for business validation and authorization. A consumer may be allowed to call an endpoint and still submit an invalid order. Quotas and burst protection address traffic behavior rather than the business correctness of a payload.', 'A partner-facing order API can have controlled access and traffic policies before forwarding to the receiving application.', 'An API proxy is not the business database or a complete replacement for backend rules.', 'Will a traffic quota prevent a valid caller from submitting an invalid product code?', 'No. That requires payload or business validation in the appropriate processing layer.', source('integration', 'introducing-sap-api-management_dd668e10-08ab-4763-9342-3e6cc7e74c18')),
      section('Cloud Integration and message processing', 'An integration flow connects a sender to processing steps and a receiver. Adapters deal with endpoint protocols. Mapping transforms one data structure into another. Routing chooses a processing path; exception handling defines behavior when processing fails.\n\nFollow the message through the flow. Its body carries the payload; headers and properties provide processing context. Keep environment-specific settings separate from reusable business logic. Deploying the flow and observing a real message are different activities.', 'Receive an order, check required data, convert field names and values, choose the target, call the receiving API, and record a meaningful result.', 'Adapters, mappings, and routers solve different problems.', 'Which step converts a shop field structure into the receiving SAP structure?', 'Mapping or transformation. The adapter handles connectivity, not the whole business mapping.', source('integration', 'introducing-cloud-integration_b3692797-cbf6-44ac-9b05-20b77411fa96')),
      section('Event-driven architecture and Event Mesh', 'An event reports something that has happened. Producers publish events without requiring every consumer to process them immediately. Subscription and queue design determines which consumers receive messages and how they are buffered. Asynchronous processing reduces direct timing dependencies but introduces questions about retries, order, and duplicate effects.\n\nSAP Event Mesh, the Event Mesh capability within Integration Suite, and Advanced Event Mesh are related offerings with different scope. Do not assume a feature or limit from one applies to all. For conceptual questions, identify the producer, event, broker, and consumer first.', 'OrderCreated can notify separate fulfillment and analytics consumers, each with its own processing responsibility.', 'Asynchronous acceptance does not mean that every consumer has finished.', 'Why should a consumer consider duplicate deliveries?', 'A retry can repeat delivery. Processing should avoid creating the same business effect twice.', source('integration', 'introducing-event-driven-architectures')),
      section('Applied revision: failures and troubleshooting', 'Use a correlation identifier to connect evidence across systems. Determine whether a failure occurred at authentication, mapping, transport, or business validation. A timeout and an invalid product code should not receive the same recovery action.\n\nFor your project, decide when retry is safe, how duplicates are detected, and how unresolved messages reach an operator. Avoid unlimited retries for a permanently invalid request. Test realistic failures and record what the receiving system did before deciding to replay a message.', 'If an order call times out, the receiver may already have created the order. Check its outcome or use a designed duplicate-protection mechanism before repeating creation.', 'A timeout means the caller lacks a confirmed result; it does not prove that nothing happened.', 'Should you blindly repeat every timed-out create request?', 'No. First account for the possibility that the original request succeeded and prevent duplicate business effects.', source('integration', 'describing-the-integration-strategy-of-sap_b4888fe7-2084-40f1-a89b-ca0f93933c78')),
    ],
  },
  administration: {
    title: 'Administering SAP Integration Suite',
    intro: 'Administration makes integration reliable for the people who depend on it. Learn to plan access and environments, maintain secure connectivity, and detect and investigate failures across the suite.',
    coverage: 'The five course units: platform context, planning, capabilities, connectivity, and monitoring.',
    terms: [['ISA-M', 'SAP Integration Solution Advisory Methodology: guidance for integration requirements and architecture.'], ['Role collection', 'A grouping used to assign related application permissions.'], ['Credential / certificate', 'Authentication material / an identity and trust artifact.'], ['Throughput / latency', 'Work processed over time / time taken for a request or message.']],
    sections: [
      section('BTP and Integration Suite', 'Integration Suite is a service within BTP. The surrounding platform provides account context, commercial allocation, identity configuration, and access to other capabilities. Administration therefore crosses the boundary between the BTP account and the integration tools themselves.\n\nKnow which component owns a setting. A problem may be caused by a platform role, an inactive capability, a service configuration, or the integration artifact. Treating every issue as an iFlow bug wastes time.', 'When a new developer cannot open a capability, investigate setup and authorization before editing the integration flow.', 'Platform access and capability-specific access are related but separate.', 'Does access to BTP cockpit prove access to every integration capability?', 'No. The appropriate service configuration and permissions still need to be in place.', source('administration', 'explaining-the-connection-between-sap-business-technology-platform-and-sap-integration-suite')),
      section('Planning and administering', 'ISA-M helps structure the assessment of integration requirements and future architecture. Planning identifies systems, interaction styles, responsibilities, and the capabilities that fit them. It should happen before uncontrolled growth of point-to-point connections.\n\nEstablish environment boundaries and appropriate roles for developers, operators, and administrators. Decide who can change productive configuration and who responds to incidents. A repeatable administrative process is easier to audit and support than individual undocumented fixes.', 'Separate the ability to inspect message status from the ability to change productive security settings.', 'Architecture methodology guides decisions; it does not itself execute an integration.', 'Is ISA-M an adapter used to send an order?', 'No. It is a methodology for assessing and designing integration.', source('administration', 'understanding-the-isa-m-methodology-for-sap-integration-suite')),
      section('Capability responsibilities', 'Cloud Integration addresses message processing; API Management addresses API exposure and governance; Event Mesh addresses event communication. The suite also includes specialized capabilities for other integration needs. Availability and activation depend on the service context and plan.\n\nAn administrator must understand enough of each selected capability to manage access and operations. A queue backlog, a failed message transformation, and API traffic rejection may appear in different tools because they belong to different responsibilities.', 'Start investigating a growing queue with the event delivery and consumer path, not by assuming the API proxy’s documentation is incorrect.', 'Monitor the capability that owns the failing stage.', 'Are API analytics and message-processing logs interchangeable?', 'No. They describe different parts of an integration and can complement each other.', source('administration', 'understanding-capabilities')),
      section('Secure connectivity', 'Connectivity includes the protocol, network path, identity, and trust between components. An adapter supports a protocol; it does not automatically create all required credentials or backend permissions. Connections to cloud endpoints and internal systems may require different setup.\n\nMaintain the lifecycle of credentials and certificates, and understand which component authenticates to which target. When troubleshooting, separate a network failure from a trust failure, an authentication failure, and an authorization rejection. Each points to a different corrective action.', 'A certificate expiry can interrupt a previously working integration even though the mapping and endpoint address have not changed.', 'Reachability is only one part of a secure working connection.', 'Does a reachable endpoint prove that its credentials and permissions are correct?', 'No. Connectivity, authentication, and authorization must each succeed.', source('administration', 'introduction-to-connectivity')),
      section('Monitoring and incident response', 'Monitor both technical health and business outcomes. Message status helps locate processing failures; throughput and response-time measurements reveal load or delay. API Management, Cloud Integration, and Event Mesh expose different operational evidence.\n\nAn alert should tell an owner what needs attention. For an incident, record the affected flow, time, identifier, recent change, and failure stage. Confirm the receiver’s result before replaying work that could create duplicates. Central monitoring can complement local tools when the process crosses several systems.', 'For a missing shipment notification, trace the relevant message and check whether it was accepted, processed, forwarded, and acted on.', 'A running service is not proof that every business message succeeded.', 'What evidence helps follow one failed transaction through multiple components?', 'A consistent business or correlation identifier together with timestamps and component-level status.', source('administration', 'introduction-to-monitoring')),
    ],
  },
  btp: {
    title: 'Exploring SAP Business Technology Platform',
    intro: 'Understand what BTP contributes to an SAP landscape, how its services are organized, and how development, integration, data, AI, and security work together. Start here before learning the operational and programming details.',
    coverage: 'All six course units, with the 21 lesson recaps included below.',
    terms: [
      ['ERP / S/4HANA', 'The business application that manages core transactions and processes.'],
      ['BTP', 'A platform for building, extending, integrating, and operating solutions.'],
      ['Entitlement / quota', 'Permission to use a service plan / the allocated amount.'],
      ['Instance / binding', 'A provisioned service resource / its connection to an application.'],
      ['Authentication / authorization', 'Establish identity / decide which operations are permitted.'],
    ],
    sections: [
      section('Strategy: place BTP in the business landscape',
        'An enterprise has connected business processes, even when its software is split across products. S/4HANA handles core ERP work; SuccessFactors, Ariba, Concur, and customer-experience applications serve other business areas. BTP supplies technology to connect and extend this landscape. It is not a replacement name for S/4HANA.\n\nThe current course connects this to SAP’s autonomous-enterprise vision: governed AI supports execution while people retain goals and oversight. In cloud terminology, SaaS supplies an application, PaaS supplies an application platform, and IaaS supplies infrastructure. Public/private/hybrid describes deployment, which is a different classification.',
        'Your shop accepts an order. ERP handles its business transaction; a BTP extension can provide a custom approval screen or connect the shop’s order flow to ERP.',
        'For a scenario question, identify the business responsibility before choosing a technology.',
        'Does adding a custom approval application mean replacing ERP with BTP?',
        'No. The approval application extends the process. ERP can remain the system handling core business transactions.', btpUnits[0].lessons[0].url),
      section('Architecture: accounts, services, and connectivity',
        'A global account is the top-level commercial and administrative container. Directories optionally organize subaccounts. A subaccount is associated with a region and is where you manage the services and environments used by solutions. Entitlements and quotas allocated from the global account determine what can be provisioned.\n\nA service plan describes an offering. A service instance is a provisioned resource; a subscription gives access to a subscribed application. The cockpit is the administration interface. A destination stores connection details for a remote target. Connectivity with Cloud Connector supports access to exposed on-premise resources; creating a destination alone does not make an inaccessible target reachable.',
        'Create separate development and production subaccounts. Give the development subaccount the plan it needs, provision the resource, then connect the application to it.',
        'Available entitlement, provisioned instance, application binding, and user permission are separate concepts.',
        'A service is entitled but your app has no connection configuration. Is entitlement enough?',
        'No. Entitlement allows provisioning. The resource and its application connection still need to be configured.', btpUnits[1].lessons[1].url),
      section('Development: UI, services, automation, and workspaces',
        'Choose a tool according to the layer you are building. CAP helps implement business services using models and application logic. SAPUI5 is a web UI framework; Fiori elements uses service metadata and annotations to provide standard business screens. ABAP-based development is another path, rather than a prerequisite for every Node.js CAP application.\n\nSAP Build brings together application development, automation, and digital workspace capabilities. A workflow coordinates business steps; a user interface lets a person interact with them. Work Zone provides a place to access applications. These responsibilities can be combined in one solution without becoming the same thing.',
        'A product-maintenance app could use a Fiori elements interface, a CAP service, and an approval workflow for publishing a price change.',
        'CAP is not the UI, and a launch site is not the service that stores your business records.',
        'Which layer should enforce a price rule even when callers bypass the screen?',
        'The backend service. UI guidance improves usability, but callers can invoke the service directly.', btpUnits[2].lessons[1].url),
      section('Integration: API contracts and connected processes',
        'An API is the interface through which software requests or exchanges information. Understand the operations, payload, authentication, and errors before consuming it. Business Accelerator Hub helps discover SAP interfaces and explore supported sandbox APIs. A sandbox demonstrates a contract using test data; it is not your company’s production backend.\n\nIntegration Suite connects SAP and non-SAP applications. At a high level, API Management governs exposed interfaces, Cloud Integration processes messages, and event messaging decouples producers and consumers. Select capabilities by the communication problem rather than assuming that every integration needs the same components.',
        'A shop’s order payload may need validation and transformation before it matches an SAP sales-order API. Finding the API is only the start of designing that flow.',
        'Discovering an API, managing access to it, and transforming messages are different tasks.',
        'Does a successful sandbox request prove that your production user has permission?',
        'No. Production connectivity, credentials, permissions, and data are configured separately.', btpUnits[3].lessons[1].url),
      section('AI and data: match capabilities to the problem',
        'Business AI depends on relevant business data and governance. HANA Cloud is a database foundation used by data-intensive and intelligent applications; it is not the ERP application itself. Data quality and context affect whether an AI result is useful.\n\nSAP AI Core supports running AI workloads; AI Launchpad supports their management. The generative AI hub provides access to generative AI capabilities, while Document AI addresses understanding business documents. Distinguish extracting fields from an invoice from executing the accounting transaction that uses those fields.',
        'An invoice-processing flow can extract supplier and amount fields, validate them against business rules, and route an uncertain result for human review.',
        'A model output is an input to a business process, not automatic proof that the process is correct.',
        'Does Document AI replace all steps in invoice processing?',
        'No. Document collection, validation, approvals, and posting still belong to the wider application process.', btpUnits[4].lessons[2].url),
      section('Security: identity, roles, and trust',
        'Authentication establishes who the caller is. Authorization decides what that caller can do. Platform users operate the environment; business users work in its applications. Permission to administer a platform and permission to edit a business record are different responsibilities.\n\nAn identity provider handles identity and sign-in. Identity Authentication supports centralized authentication; Identity Provisioning supports identity lifecycle synchronization. XSUAA participates in authorization and trust flows for Cloud Foundry applications. Applications must validate trusted tokens and enforce their required permissions. A login screen alone is not access control for every backend operation.',
        'A product viewer and a product manager can both sign in. Only the manager should be allowed to change a price through the API.',
        'Successful authentication does not imply unrestricted authorization.',
        'A signed-in user cannot delete a product. Must authentication be broken?',
        'No. Sign-in may be working correctly while authorization intentionally denies deletion.', btpUnits[5].lessons[2].url),
    ],
    lessons: btpUnits,
  },
  operations: {
    title: 'Operating SAP Business Technology Platform',
    intro: 'Learn how to organize, secure, connect, monitor, and govern a BTP landscape. The operational question is not just whether an app works today, but who owns it, how it recovers, and how its resources are controlled.',
    coverage: 'The nine course units, summarized as operational decisions and concepts.',
    terms: [['Global account', 'Top-level account for commercial allocation and governance.'], ['Cloud Foundry / Kyma / ABAP', 'Different environments for application workloads.'], ['RTO / RPO', 'Target recovery time / tolerable data-loss window.'], ['Logs / metrics / traces', 'Event records / numerical measurements / a request’s path.']],
    sections: [
      section('Responsibilities and governance', 'Operating a platform requires clear ownership. Decide who may provision services, assign access, approve changes, respond to incidents, and review consumption. A managed platform still leaves application configuration and operating procedures to the customer.\n\nGovernance makes those responsibilities repeatable. Agree on naming, environment separation, access reviews, and how projects request resources. Use SAP guidance as a starting point and record the decisions that apply to your organization.', 'For your product project, name an application owner, a platform administrator, and a person responsible for failed-order alerts.', 'Governance is an operating model, not just a list of cloud services.', 'Does a cloud provider eliminate the need for an application owner?', 'No. Someone must still own application behavior, configuration, users, and response to business failures.', source('operations', 'illustrating-the-intelligent-sustainable-enterprise_df1d2992-a95a-487a-9a06-7226bebbb11d')),
      section('Account structure and service governance', 'Organize subaccounts around technical and business boundaries such as environment, region, and ownership. Directories help group them. Distribute entitlements and quotas deliberately rather than letting every project consume everything.\n\nProvisioning a service, subscribing to an application, and giving a user access are separate steps. If a service is missing, investigate plan availability, region, entitlement, and permissions before assuming the cockpit is broken.', 'Keep a test integration’s resources separate from the production order flow and label who pays for each.', 'The cockpit shows the resources in your selected account context.', 'Why verify the selected subaccount before making a change?', 'The same type of resource may exist in several environments. Changing the wrong one can affect another application or production.', source('operations', 'utilizing-sap-btp-cockpit')),
      section('Runtime environments', 'Cloud Foundry simplifies application deployment and operations using platform conventions and buildpacks. Kyma offers a managed Kubernetes-based runtime for containerized workloads. The ABAP environment supports cloud development in ABAP.\n\nSelect an environment for the workload and your team’s skills. Administration differs: Cloud Foundry has organizations and spaces, Kubernetes has its own resources and access model, and ABAP has environment-specific administration. Knowing one does not mean every command or role transfers unchanged.', 'A Node.js CAP learning app can fit Cloud Foundry; an existing Kubernetes architecture may require a different operational approach.', 'A programming language, a framework, and a runtime are different choices.', 'Does using BTP require rewriting all Node.js code in ABAP?', 'No. BTP supports multiple development environments and languages.', source('operations', 'describing-runtime-environments')),
      section('Identity and access management', 'Separate the identity lifecycle from access to a particular operation. Identity Authentication supports sign-in and federation. Identity Provisioning distributes identities and relevant assignments between systems. Authorization determines what the authenticated caller can do.\n\nAssign roles to the right users or groups and review them when responsibilities change. Platform and application permissions need separate attention; runtime-specific permissions may also apply. Give a person the rights needed for the job rather than every available administrator role.', 'A support employee can investigate an incident without automatically receiving permission to change product prices.', 'Authentication, provisioning, and authorization solve three different problems.', 'Which service category concerns synchronizing users between systems?', 'Identity provisioning. Authentication is concerned with sign-in.', source('operations', 'explaining-identity-and-access-management-on-sap-btp')),
      section('Setup and configuration tools', 'Boosters guide and automate setup for selected scenarios. Command-line tools support repeatable administration. Terraform expresses infrastructure configuration declaratively; kubectl addresses Kubernetes resources. Automation Pilot supports operational automation.\n\nChoose the tool for the environment and task. Automation should still have documented inputs, permissions, and ownership. Review what a setup flow creates so you can operate and troubleshoot the resulting resources.', 'Record the services and roles created during a guided setup so that another developer can understand the environment later.', 'A booster accelerates setup; it does not remove the need to understand the result.', 'Is kubectl the general command-line tool for every BTP environment?', 'No. It targets the Kubernetes API. Use the tool appropriate to the environment.', source('operations', 'using-boosters')),
      section('Connectivity', 'Destinations hold information used to reach remote systems. For the Cloud Foundry connectivity scenario, Cloud Connector supports a controlled tunnel to exposed on-premise resources. An internet-accessible service and an on-premise target have different network requirements.\n\nTroubleshoot in layers: target reachability, destination configuration, authentication, and backend authorization. A working network path does not prove that credentials are valid; valid credentials do not prove that the business operation is permitted.', 'If the order API returns a permission error, changing the destination’s host is unlikely to fix the missing business authorization.', 'Connection configuration is not permission to execute every operation.', 'Can a destination alone expose an unreachable internal server?', 'No. The required network path and allowed resources must also be configured.', source('operations', 'analyzing-connectivity-in-sap-btp_e525e7d8-20a0-41f7-8b79-eec4aad834a8')),
      section('High availability and disaster recovery', 'High availability reduces service interruption when components fail. Disaster recovery concerns restoring operation after a larger disruption. Redundancy and backups address different failure modes.\n\nRTO is the target time to recover; RPO is the tolerated data-loss window. These are objectives you design and test for, not automatic promises created by choosing a region. Understand service-specific capabilities and the application’s recovery procedure.', 'An order system might target recovery within one hour and loss of no more than five minutes of accepted data. Those are two separate requirements.', 'RTO measures recovery time; RPO measures the data-loss window.', 'Which objective asks how much recent data the business can lose?', 'RPO. RTO instead asks how quickly service must be restored.', source('operations', 'explaining-high-availability-and-disaster-recovery-concepts-for-sap-btp')),
      section('Observability and monitoring', 'Logs record events, metrics quantify behavior over time, and traces help follow requests across components. Monitoring detects conditions you watch for; observability helps investigate why a system behaved as it did.\n\nUse local tools for component-level detail and central tools for the wider process. SAP Cloud ALM supports end-to-end operational monitoring. Useful alerts need an owner and a response procedure; collecting data without acting on it does not resolve failures.', 'Track an order identifier through the integration and receiving application. This helps distinguish a transport failure from a business rejection.', 'A technically running application can still fail the business process.', 'Why combine component logs with end-to-end monitoring?', 'A request may cross several healthy components and still fail between them or at a business validation step.', source('operations', 'explaining-the-observability-strategy-of-sap-btp')),
      section('Cost and usage management', 'Consumption-based and subscription-based commercial models allocate cost differently. Pay-As-You-Go charges for usage; enterprise consumption agreements use their contracted arrangements; subscriptions cover a defined service scope. Free tier refers to eligible plans, not unlimited free access to every service.\n\nReview actual consumption against allocations and ownership. Quotas, entitlements, and invoices answer different questions: what is allowed, what is allocated, and what was charged. Retire unused resources through your normal change process.', 'A forgotten learning database can remain a resource to review even after the application using it is no longer active.', 'Availability in the service catalog does not mean zero cost.', 'Does unused entitlement necessarily equal consumed service usage?', 'No. Permission or allocation to use a resource is different from actually consuming it.', source('operations', 'analyzing-sap-business-technology-platform-sap-btp-_ae0a22bc-793e-4210-a3ab-fb3dc26c848f')),
    ],
  },
  cloudFoundry: {
    title: 'Developing Applications for SAP BTP, Cloud Foundry Runtime',
    intro: 'Understand the journey from application source to a running, reachable, observable cloud service. Focus on what the platform manages and what your application still has to do correctly.',
    coverage: 'All five course units, including deployment, scaling, monitoring, and advanced considerations.',
    terms: [['Buildpack', 'Prepares the runtime and dependencies during staging.'], ['Droplet', 'The staged artifact used to run the application.'], ['Route', 'An address mapped to an application.'], ['Restart / restage', 'Run the existing droplet again / rebuild the staged artifact.'], ['Horizontal / vertical scaling', 'Change instance count / change resources per instance.']],
    sections: [
      section('Runtime fundamentals', 'Cloud Foundry supplies a managed environment for deploying applications without configuring every underlying server. Buildpacks prepare supported application stacks; the runtime starts instances and routes requests to them. Managed services provide capabilities such as persistence and security.\n\nAn organization and its spaces organize resources and access. An app instance is a running copy of your application. A route determines how a caller reaches it. These are separate: an app can be started but unavailable to a caller because routing or access is incorrect.', 'Think of your Node.js process as one instance; the platform can start additional copies and route incoming traffic.', 'The platform manages execution, but your code still defines business behavior.', 'Is an application route the same thing as an application instance?', 'No. A route is an address mapping; instances execute the application.', source('cloudFoundry', 'explaining-the-benefits-of-the-sap-btp-cloud-foundry-runtime_d0ee3ab4-ad09-4216-9c20-ebf38ec0da9e')),
      section('Designing a cloud-ready application', 'Keep persistent data outside an instance’s local filesystem and avoid relying on one process’s memory for shared business state. Instances can be replaced or scaled independently. Read environment configuration and service connection information rather than embedding deployment-specific settings in source.\n\nThe application must start using the platform’s expected conventions, including its assigned port. In a multitenant application, tenant isolation must be part of the design. Sharing infrastructure must not expose one customer’s data to another.', 'If you store orders only in an in-memory array, a new instance starts without them. Use a persistent service for business records.', 'Scaling exposes assumptions about local state.', 'Why can a session stored only in one instance’s memory cause problems?', 'Another instance may receive the next request and not have that session. Use an appropriate shared or stateless session design.', 'https://docs.cloudfoundry.org/devguide/deploy-apps/prepare-to-deploy.html'),
      section('Deployment and lifecycle', 'Deployment involves selecting the target, uploading the application, staging it, and starting instances. A manifest can describe settings such as memory, routes, and service bindings. A multi-target application describes related modules and dependencies as one application package.\n\nA restart runs the existing staged artifact again; a restage rebuilds it, which matters when buildpack-provided dependencies must change. Deployment strategies can reduce interruption, but database compatibility still needs planning. Keep a verification and rollback approach alongside the deployment procedure.', 'After deploying a product service, verify its health and a real read request. A successful upload alone is not proof that the application works.', 'Staging success, process startup, reachability, and business correctness are distinct checks.', 'Which lifecycle operation rebuilds the droplet?', 'Restaging. Restarting uses the existing droplet.', source('cloudFoundry', 'performing-the-deployment-process-in-sap-btp-cloud-foundry-runtime_f353b8ed-2eba-4f88-949b-939cdeae6e3e')),
      section('Operations, scaling, and troubleshooting', 'Use logs to investigate specific failures and metrics to identify patterns such as sustained memory pressure or slow responses. Preserve operational data appropriately when you need historical analysis. Health checks allow the platform to recognize an unhealthy instance, but do not validate every business rule.\n\nHorizontal scaling increases the number of instances; vertical scaling increases resources assigned to each. First identify the bottleneck: adding application instances will not necessarily fix a slow downstream database. Investigate recent configuration and deployment changes as well as resource measurements.', 'A service that times out only while calling ERP may have a downstream dependency problem rather than insufficient application memory.', 'Choose a scaling action from evidence, not from the fact that the app is slow.', 'Will doubling application instances always double throughput?', 'No. Shared dependencies, contention, and the application design can limit throughput.', source('cloudFoundry', 'discovering-observability-and-monitoring-in-sap-btp-cloud-foundry-runtime_c40235af-a73a-4013-b35a-4db73be17ca9')),
      section('Security, resilience, and advanced design', 'Applications must enforce trusted authentication and authorization. XSUAA integrates with identity providers and supports token-based access. Never treat the presence of a token as sufficient without validating it and checking permissions.\n\nResilience considers dependency failures, recovery, and appropriate redundancy. Multiple instances help with some failures; they do not replace database recovery or a plan for unavailable external systems. UI hosting, application sizing, multitenancy, and AI integration each add requirements that must fit the overall architecture.', 'An unavailable recommendation service should not automatically prevent customers from submitting a valid order if recommendations are optional.', 'Separate essential dependencies from optional enhancements.', 'Does running two instances eliminate the need for disaster recovery?', 'No. Shared services and larger outages still need a recovery strategy.', source('cloudFoundry', 'expanding-your-horizons-in-sap-btp-cloud-foundry-runtime_c8335721-15c8-4cd1-9647-39af98fddae6')),
    ],
  },
  cap: {
    title: 'Introduction to SAP Cloud Application Programming Model',
    intro: 'CAP combines domain models, service definitions, and reusable runtime behavior. Your main job is to describe the business domain clearly, then add the rules the generic runtime cannot infer.',
    coverage: 'The five course units: foundations, basic features, advanced modeling, service behavior, and common recipes.',
    terms: [['CDS / CDL / CSN', 'Modeling concepts and tools / textual definition language / structured model representation.'], ['Entity / projection', 'A modeled business structure / a service-oriented view of a model.'], ['Association / composition', 'A relationship / an ownership relationship between parent and child.'], ['Action / function', 'An operation that may change state / an operation without side effects.'], ['ETag', 'A version marker used for optimistic concurrency control.']],
    sections: [
      section('The model-driven approach', 'CAP offers common behavior for business services so you do not handwrite every CRUD operation. Describe entities and services in CDS; add Node.js or Java logic for application-specific behavior. The persistence model, public API, and user interface are related layers, not identical artifacts.\n\nA typical project puts domain definitions under db, service definitions and handlers under srv, and UI modules under app. Service projections can expose the fields and entities appropriate to a use case without making every internal detail public.', 'Model Products once, then expose a catalog service that offers only the fields shoppers need.', 'The runtime supplies reusable behavior; it cannot invent your company’s business rules.', 'Why avoid exposing every database field automatically?', 'Internal fields may be irrelevant or sensitive, and the API contract should reflect the consumer’s use case.', source('cap', 'exploring-the-fundamental-concepts_aa4b7679-e1fe-462e-81c3-9a94f1f06647')),
      section('Entities, services, and persistence', 'An entity has named, typed elements and a key identifying records. CDS models can be translated into persistence artifacts and used in service definitions. Choose types and constraints that express the business meaning: a price, identifier, and description serve different purposes.\n\nA service exposes a controlled interface to these models. OData metadata describes its schema, while requests read or modify records. Local SQLite helps the development loop, but a local test does not prove that production configuration, access control, and database behavior are correct.', 'A Product could have an ID, name, price, and category relationship. The public catalog might omit an internal cost field.', 'An entity definition describes structure; a record is one instance of that structure.', 'Is the service API necessarily identical to the underlying table?', 'No. A service can use projections and expose a purpose-specific contract.', source('cap', 'defining-domain-models_b61bc48e-26e6-4095-aa03-122bdffed06a')),
      section('Relationships, ownership, and reusable aspects', 'Use associations to represent relationships between independently meaningful entities. A managed to-one association lets CDS derive the foreign key from the target key. Unmanaged associations specify their relationship condition explicitly. Cardinality describes how many related records are possible.\n\nCompositions express a parent-child ownership relationship and support document-style structures such as an order with its items. Reusable aspects keep common definitions consistent; managed fields can record who created or modified a record and when. Choose modeling semantics according to lifecycle, not merely how convenient a nested response looks.', 'Products and Categories have an association. An Order and the line items that belong to that order are a natural composition example.', 'A relationship does not always imply ownership.', 'Should deleting a product category automatically mean deleting every product?', 'Not merely because they are associated. Model and implement the intended lifecycle explicitly.', source('cap', 'using-associations-and-compositions_c6bad664-2d1a-4211-9076-c3a1213f176a')),
      section('Validation, handlers, and business operations', 'Validate input at the service boundary. Declarative annotations such as mandatory fields and ranges express common constraints. Custom logic handles rules involving business context. A before handler validates or prepares a request, an on handler implements or intercepts its processing, and an after handler can enrich the result.\n\nActions model operations that may change state; functions are side-effect-free. Returning a friendly UI error is not enough if a direct API request can still write invalid data. Think through create, partial update, and missing-field cases separately.', 'An action can submit an order. A price validation rule should also be checked when a client calls the API without using the Fiori screen.', 'UI validation improves feedback; backend validation protects the service contract.', 'Where would you normally reject invalid input before generic create processing?', 'A before handler or an appropriate declarative constraint, depending on the rule.', source('cap', 'validating-user-input_cf5c3632-76f4-4ac2-a277-1e2228067ca6')),
      section('Authorization, concurrency, and localized behavior', 'Authorization expresses who can use a service or operation, including restrictions on records. CAP’s authorization annotations let services declare requirements, but productive identity configuration and role assignment must still be correct.\n\nOptimistic concurrency uses a version indicator such as an ETag to detect stale writes. It addresses two users overwriting each other’s work. Localization moves user-facing text into language-specific resources; it does not change the business rule or grant permissions. Learn these as separate concerns even when one screen uses all three.', 'Two managers open a product. After one updates it, the other should not unknowingly overwrite the newer value. A localized conflict message can explain the problem.', 'Authorization asks whether a write is allowed; concurrency asks whether it is based on a current version.', 'Does translating an error message change the validation behavior?', 'No. It changes how the result is communicated, not the underlying rule.', source('cap', 'localizing-error-messages_adfea1cd-101f-4455-ae34-4940cda8b7ff')),
    ],
  },
}
